def mark_shipped_orders_paid(apps, schema_editor):
    """Orders that were already shipped before payment tracking existed were fulfilled,
    so treat them as paid. Everything else stays pending for the shop owner to review."""
    Order = apps.get_model('payment', 'Order')
    Order.objects.filter(shipped=True).update(payment_status='paid')


